mapper.select:
select ca.*
from cap_account_monthly_balance ca
where ca.period = #{period}
  and ca.bank_account_id = #{bankAccountId}

select ca.*
from cap_account_monthly_balance ca
where ca.balance_date = #{balanceDate}
  and ca.bank_account_id = #{bankAccountId}

select ca.*
from cap_account_monthly_balance ca
where ca.period < #{period}
  and ca.bank_account_id = #{bankAccountId}
  order by ca.period desc

select ca.*
from cap_account_monthly_balance ca
where ca.balance_date < #{balanceDate}
  and ca.bank_account_id = #{bankAccountId}
  order by ca.period desc

select ca.*
from cap_account_monthly_balance ca
where ca.period > #{period}
  and ca.bank_account_id = #{bankAccountId}
  order by ca.period asc

select ca.*
from cap_account_monthly_balance ca
where ca.balance_date > #{balanceDate}
  and ca.bank_account_id = #{bankAccountId}
  order by ca.period asc

select ca.*,cam.period last_period,t.investment_amount restricted_amount from ( select cba.bank_account_id,cb.bank_name,cba.bank_branch_name,cba.bank_account_num,cba.bank_account_name,fc.currency_code currency, fc.currency_name,ca.balance_id,ca.opening_balance,ca.received_amount, ca.paid_amount,ca.other_amount,ca.account_balance,ca.balance_status,ca.company_id from csh_bank_account cba left join csh_bank cb on cba.bank_id = cb.bank_id left join fnd_currency fc on fc.currency_code = cba.currency left join cap_account_monthly_balance ca on ca.bank_account_id = cba.bank_account_id
and ca.period = #{period}
where cba.company_id = #{request.companyId}
and cba.bank_account_id = #{bankAccountId}
)ca left join cap_account_monthly_balance cam on cam.bank_account_id = ca.bank_account_id and cam.balance_status = 'FULL' and cam.period >= all ( select period from cap_account_monthly_balance where bank_account_id = cam.bank_account_id and balance_status = 'FULL' ) left join (select inv.bank_account_id,sum(inv.investment_amount) investment_amount from inv_finance_purchase inv where inv.purchase_status = 'APPROVED'
and to_char(inv.CREATION_DATE,'yyyy-mm')>= #{period}
and inv.purchase_date > to_char(now( ), 'YYYY-MM-DD') group by inv.bank_account_id) t on t.bank_account_id = ca.bank_account_id
where 1 = 1
and t.investment_amount > #{restrictedAmount}
and ca.bank_name like concat("%",concat(#{bankName}, "%"))
and ca.bank_branch_name like concat("%",concat(#{bankBranchName}, "%"))
and ca.bank_account_num like concat("%",concat(#{bankAccountNum}, "%"))
and ca.bank_account_name like concat("%",concat(#{bankAccountName}, "%"))
order by ca.bank_account_id

SELECT cba.bank_branch_name, cba.bank_account_name, (SELECT currency_name FROM fnd_currency WHERE currency_code = cba.currency) currency_name, (SELECT fc.company_full_name FROM fnd_company fc WHERE fc.company_id = cba.company_id) company_name, cb.bank_name, cba.bank_account_num, cba.bank_account_type, (SELECT svb.meaning FROM sys_code_b sb, sys_code_value_b svb WHERE sb.code_id = svb.code_id AND svb.value = cba.bank_account_type AND svb.enabled_flag = 'Y' AND sb.code = 'CSH.BANK_ACCOUNT_TYPE') bank_account_type_desc, cba.company_id, cba.bank_account_id, nvl(cba.valid_flag, 'N') is_valid, (case when cba.valid_flag = 'Y' then '是' else '否' end) is_valid_desc, (case when cba.valid_flag = 'Y' then 0 else (nvl((SELECT account_balance FROM cap_account_monthly_balance cab WHERE cab.bank_account_id = cba.bank_account_id AND cab.balance_date = (SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date <= to_date(#{balanceDate},'YYYY-MM-DD') AND bank_account_id = cba.bank_account_id)), 0) + nvl(t.amount, 0)) end) available_amount, (case when cba.valid_flag = 'Y' then (nvl((SELECT account_balance FROM cap_account_monthly_balance cab WHERE cab.bank_account_id = cba.bank_account_id AND cab.balance_date = (SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date <= #{balanceDate} AND bank_account_id = cba.bank_account_id)), 0) + nvl(t.amount, 0)) else 0 end) restricted_amount, 0 investment_amount, --投资余额 (nvl((SELECT account_balance FROM cap_account_monthly_balance cab WHERE cab.bank_account_id = cba.bank_account_id AND cab.balance_date = (SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date <= to_date(#{balanceDate},'YYYY-MM-DD') AND bank_account_id = cba.bank_account_id)), 0) + nvl(t.amount, 0) + 0) account_balance, --账户余额 = 上期结存+本段期间收支 nvl(t.received_amount, 0) received_amount, nvl(t.paid_amount, 0) paid_amount, nvl((SELECT balance_status FROM cap_account_monthly_balance cab WHERE cab.bank_account_id = cba.bank_account_id AND cab.balance_date = (SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date >= to_date(#{balanceDate},'YYYY-MM-DD') AND bank_account_id = cba.bank_account_id) ), 'NOT') balance_status, nvl((SELECT other_amount FROM cap_account_monthly_balance cab WHERE cab.bank_account_id = cba.bank_account_id AND cab.balance_date = (SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date <= to_date(#{balanceDate},'YYYY-MM-DD')) AND bank_account_id = cba.bank_account_id), 0) other_amount, (SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE bank_account_id = cba.bank_account_id AND balance_status = 'FULL' AND balance_date <= to_date(#{balanceDate},'YYYY-MM-DD')) last_balance_date, to_date(#{balanceDate},'YYYY-MM-DD') balance_date, (SELECT MAX(balance_id) FROM cap_account_monthly_balance WHERE bank_account_id = cba.bank_account_id AND balance_date <= to_date(#{balanceDate},'YYYY-MM-DD')) balance_id, nvl(inv.unlimited_amount,0) inv_unlimited_amount, nvl(inv.limited_amount,0) inv_limited_amount FROM csh_bank_account cba,csh_bank cb, (SELECT SUM(st.amount) amount, SUM(st.received_amount) received_amount, SUM(st.paid_amount) paid_amount, bank_account_id FROM (SELECT SUM(nvl(transaction_amount, 0)) amount, SUM(nvl((case when direction ='IN' then transaction_amount else 0 end), 0)) received_amount, SUM(nvl((case when direction = 'OUT' then -transaction_amount else 0 end), 0)) paid_amount, bank_account_id, transaction_date FROM ( --收款 SELECT CT.BANK_ACCOUNT_ID, CT.TRANSACTION_AMOUNT, CT.TRANSACTION_DATE, 'IN' DIRECTION FROM CSH_TRANSACTION CT WHERE CT.REVERSED_FLAG = 'N' AND CT.TRANSACTION_TYPE = 'RECEIPT' --退款 UNION ALL SELECT CT.BANK_ACCOUNT_ID, -CT.TRANSACTION_AMOUNT, CT.TRANSACTION_DATE, 'OUT' DIRECTION FROM CSH_TRANSACTION CT WHERE CT.REVERSED_FLAG = 'N' AND CT.TRANSACTION_TYPE = 'REFUND' UNION ALL --付款 SELECT CT.BANK_ACCOUNT_ID, -CT.TRANSACTION_AMOUNT, CT.TRANSACTION_DATE, 'OUT' DIRECTION FROM CSH_TRANSACTION CT WHERE CT.REVERSED_FLAG = 'N' AND CT.TRANSACTION_TYPE = 'PAYMENT' UNION ALL --融资收款 SELECT CLCBA.BANK_ACCOUNT_ID, LCW.DUE_AMOUNT, LCW.DUE_DATE, 'IN' DIRECTION FROM LON_CONTRACT_WITHDRAW LCW JOIN CT_LON_CONTRACT_BANK_ACCOUNT CLCBA ON CLCBA.BANK_ACCOUNT_TYPE = 'WITHDRAWAL_ACCOUNT' AND CLCBA.CONTRACT_ID = LCW.CONTRACT_ID WHERE LCW.DATA_CLASS = 'NORMAL' AND LCW.WITHDRAW_STATUS IN ('APPROVED', 'PENDING') UNION ALL --融资还款 SELECT LCRN.BANK_ACCOUNT_ID, -LCRN.DUE_AMOUNT, LCRN.DUE_DATE, 'OUT' DIRECTION FROM LON_CONTRACT_WITHDRAW LCW JOIN LON_CONTRACT_REPAYMENT_LN LCRN ON LCW.WITHDRAW_ID = LCRN.WITHDRAW_ID WHERE LCW.DATA_CLASS = 'NORMAL' UNION ALL --资金调拨 拨出 SELECT EFTL.OUT_BANK_ACCOUNT_ID, -EFTL.ACTUAL_PAY_AMOUNT, EFTL.ACTUAL_PAY_DATE, 'OUT' DIRECTION FROM EFT_FUND_TRANSFER_LIST EFTL WHERE EFTL.TRANSFER_STATUS = 'CONFIRM' AND EFTL.DATA_CLASS = 'NORMAL' AND EFTL.TRANSFER_TYPE IN ('TRANSFER', 'PAY') AND ( nvl(EFTL.SOURCE_DOC_CATEGORY,'N')!='LON_CONTRACT_REPAYMENT' OR ( EFTL.SOURCE_DOC_CATEGORY='LON_CONTRACT_REPAYMENT' AND nvl(EFTL.TRANSFER_TYPE,'N')!='PAY'))
UNION ALL --资金调拨 拨入 SELECT EFTL.IN_BANK_ACCOUNT_ID, EFTL.ACTUAL_PAY_AMOUNT, EFTL.ACTUAL_PAY_DATE, 'IN' DIRECTION FROM EFT_FUND_TRANSFER_LIST EFTL WHERE EFTL.TRANSFER_STATUS = 'CONFIRM' AND EFTL.DATA_CLASS = 'NORMAL' AND EFTL.TRANSFER_TYPE IN ('TRANSFER', 'PAY') AND ( nvl(EFTL.SOURCE_DOC_CATEGORY,'N')!='LON_CONTRACT_REPAYMENT' OR ( EFTL.SOURCE_DOC_CATEGORY='LON_CONTRACT_REPAYMENT' AND nvl(EFTL.TRANSFER_TYPE,'N')!='PAY'))
UNION ALL --ABS/ABN 资产转让收款确认 SELECT CBBA.BANK_ACCOUNT_ID, CAPR.RECEIPT_AMOUNT, CAPR.RECEIPT_DATE, 'IN' DIRECTION FROM CT_ABS_PRODUCT CAP JOIN CT_ABS_PRODUCT_RECEIPT CAPR ON CAP.PRODUCT_ID = CAPR.PRODUCT_ID JOIN CT_ABS_BANK_ACCOUNT CBBA ON CBBA.ABS_BANK_ACCOUNT_ID = CAPR.ABS_BANK_ACCOUNT_ID WHERE CAP.DATA_CLASS = 'NORMAL' AND CAP.PRODUCT_STATUS IN ('APPROVED', 'PENDING') UNION ALL --ABS/ABN 回购 SELECT CAPB.BANK_ACCOUNT_ID, -CAPB.BUYBACK_AMOUNT, CAPB.BUYBACK_DATE, 'OUT' DIRECTION FROM CT_ABS_PRODUCT_BUYBACK CAPB JOIN CT_ABS_PRODUCT CAP ON CAPB.PRODUCT_ID = CAP.PRODUCT_ID WHERE CAP.DATA_CLASS = 'NORMAL' AND CAP.BUYBACK_STATUS = 'APPROVED' UNION ALL --其他发债收款 SELECT CABA.BANK_ACCOUNT_ID, CAP.ISSUE_AMOUNT, CAP.DUE_DATE_BEGIN, 'IN' DIRECTION FROM CT_ABS_PRODUCT CAP JOIN CT_ABS_BANK_ACCOUNT CABA ON CAP.PRODUCT_ID = CABA.SOURCE_KEY AND CABA.SOURCE_TYPE = 'ABS_PRODUCT' AND CABA.BANK_ACCOUNT_TYPE = 'REG_REC_ACCOUNT' AND CABA.ACCOUNT_SOURCE_TYPE = 'OUR_ACCOUNT' WHERE CAP.DATA_CLASS = 'NORMAL' AND CAP.PRODUCT_STATUS IN ('APPROVED', 'PENDING')) p WHERE transaction_date <= to_date(#{balanceDate},'YYYY-MM-DD') AND (((SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date <= to_date(#{balanceDate},'YYYY-MM-DD') AND bank_account_id = p.bank_account_id) IS NULL) OR (((SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date <= to_date(#{balanceDate},'YYYY-MM-DD') AND bank_account_id = p.bank_account_id) IS NOT NULL AND transaction_date > (SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date <= to_date(#{balanceDate},'YYYY-MM-DD') AND bank_account_id = p.bank_account_id)))) GROUP BY bank_account_id, transaction_date, DIRECTION) st GROUP BY st.bank_account_id) t, ( select ifp.bank_account_id, sum((case when ifp.is_limited ='Y' then (ifp.purchased_amount-ifp.redeemed_amount) else 0 end)) unlimited_amount, sum((case when nvl(ifp.is_limited,'N') = 'N' then (ifp.purchased_amount-ifp.redeemed_amount) else 0 end)) limited_amount from inv_finance_purchase ifp group by ifp.bank_account_id) inv where t.bank_account_id(+) = cba.bank_account_id and cba.bank_id = cb.bank_id and inv.bank_account_id(+) = cba.bank_account_id
AND cba.bank_id =#{bankId}
and cba.company_id = #{companyId}
and cba.currency = #{currency}
and cba.bank_account_id = #{bankAccountId}
and cb.bank_name like concat(concat('%',#{bankName}),'%')
order by cb.bank_id

SELECT bank_account_id, (case when direction = 'IN' then TRANSACTION_amount else NULL end) received_amount, (case when direction = 'OUT' then -transaction_amount else NULL end) paid_amount, transaction_date, (nvl((SELECT account_balance FROM cap_account_monthly_balance WHERE balance_date = ( SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date < p.transaction_date and bank_account_id = p.bank_account_id)),0) + transaction_amount) account_balance, type, bp_name, -1 balance_id, '' other_amount_description FROM ( --收款 SELECT CT.BANK_ACCOUNT_ID, CT.TRANSACTION_AMOUNT, CT.TRANSACTION_DATE, '收款-' || (SELECT DESCRIPTION FROM hls_document_type WHERE document_category = 'CSH_TRANSACTION' AND business_type = ct.business_type AND document_type = ct.transaction_type) TYPE, (SELECT bp_name FROM hls_bp_master WHERE bp_id = ct.bp_id) bp_name, 'IN' DIRECTION FROM CSH_TRANSACTION CT WHERE CT.REVERSED_FLAG = 'N' AND CT.TRANSACTION_TYPE = 'RECEIPT' --退款 UNION ALL SELECT CT.BANK_ACCOUNT_ID, -CT.TRANSACTION_AMOUNT, CT.TRANSACTION_DATE, (case when (SELECT cwo.cf_item FROM csh_write_off cwo WHERE cwo.csh_transaction_id = ct.transaction_id) = 52 then '保证金退款-' else '收款退款-' end) || (SELECT DESCRIPTION FROM hls_document_type WHERE document_category = 'CSH_TRANSACTION' AND business_type = ct.business_type AND document_type = ct.transaction_type) TYPE, (SELECT bp_name FROM hls_bp_master WHERE bp_id = ct.bp_id) bp_name, 'OUT' DIRECTION FROM CSH_TRANSACTION CT WHERE CT.REVERSED_FLAG = 'N' AND CT.TRANSACTION_TYPE = 'REFUND' UNION ALL --付款 SELECT CT.BANK_ACCOUNT_ID, -CT.TRANSACTION_AMOUNT, CT.TRANSACTION_DATE, '付款-' || (SELECT DESCRIPTION FROM hls_document_type WHERE document_category = 'CSH_TRANSACTION' AND business_type = ct.business_type AND document_type = ct.transaction_type) TYPE, (SELECT bp_name FROM hls_bp_master WHERE bp_id = ct.bp_id) bp_name, 'OUT' DIRECTION FROM CSH_TRANSACTION CT WHERE CT.REVERSED_FLAG = 'N' AND CT.TRANSACTION_TYPE = 'PAYMENT' UNION ALL --融资收款 SELECT CLCBA.BANK_ACCOUNT_ID, LCW.DUE_AMOUNT, LCW.DUE_DATE, '融资-收款' TYPE, (SELECT h.bp_name FROM lon_contract c, hls_bp_master h WHERE c.contract_id = lcw.contract_id AND c.credit_bp_id = h.bp_id) bp_name, 'IN' DIRECTION FROM LON_CONTRACT_WITHDRAW LCW JOIN CT_LON_CONTRACT_BANK_ACCOUNT CLCBA ON CLCBA.BANK_ACCOUNT_TYPE = 'WITHDRAWAL_ACCOUNT' AND CLCBA.CONTRACT_ID = LCW.CONTRACT_ID WHERE LCW.DATA_CLASS = 'NORMAL' AND LCW.WITHDRAW_STATUS IN ('APPROVED', 'PENDING') UNION ALL --融资还款 SELECT LCRN.BANK_ACCOUNT_ID, -LCRN.DUE_AMOUNT, LCRN.DUE_DATE, '融资-还款' TYPE, (SELECT h.bp_name FROM lon_contract c, hls_bp_master h WHERE c.contract_id = lcw.contract_id AND c.credit_bp_id = h.bp_id) bp_name, 'OUT' DIRECTION FROM LON_CONTRACT_WITHDRAW LCW JOIN LON_CONTRACT_REPAYMENT_LN LCRN ON LCW.WITHDRAW_ID = LCRN.WITHDRAW_ID WHERE LCW.DATA_CLASS = 'NORMAL' UNION ALL --资金调拨 拨出 SELECT EFTL.OUT_BANK_ACCOUNT_ID, -EFTL.ACTUAL_PAY_AMOUNT, EFTL.ACTUAL_PAY_DATE, (SELECT scb.meaning FROM sys_code_value_b scb, sys_code_b sb WHERE sb.code_id = scb.code_id AND sb.code = 'FT.PAYMENT_PURPOSE' AND scb.value = eftl.apply_purpose) || '-付款' TYPE, nvl((SELECT bp_name FROM hls_bp_master WHERE bp_id = eftl.bp_id), eftl.organization_name) bp_name, 'OUT' DIRECTION FROM EFT_FUND_TRANSFER_LIST EFTL WHERE EFTL.TRANSFER_STATUS = 'CONFIRM' AND EFTL.DATA_CLASS = 'NORMAL' AND EFTL.TRANSFER_TYPE IN ('TRANSFER', 'PAY') AND (nvl(EFTL.SOURCE_DOC_CATEGORY, 'N') != 'LON_CONTRACT_REPAYMENT' OR (EFTL.SOURCE_DOC_CATEGORY = 'LON_CONTRACT_REPAYMENT' AND nvl(EFTL.TRANSFER_TYPE, 'N') != 'PAY'))
UNION ALL --资金调拨 拨入 SELECT EFTL.IN_BANK_ACCOUNT_ID, EFTL.ACTUAL_PAY_AMOUNT, EFTL.ACTUAL_PAY_DATE, (SELECT scb.meaning FROM sys_code_value_b scb, sys_code_b sb WHERE sb.code_id = scb.code_id AND sb.code = 'FT.PAYMENT_PURPOSE' AND scb.value = eftl.apply_purpose) || '-收款' TYPE, nvl((SELECT bp_name FROM hls_bp_master WHERE bp_id = eftl.bp_id), eftl.organization_name) bp_name, 'IN' DIRECTION FROM EFT_FUND_TRANSFER_LIST EFTL WHERE EFTL.TRANSFER_STATUS = 'CONFIRM' AND EFTL.DATA_CLASS = 'NORMAL' AND EFTL.TRANSFER_TYPE IN ('TRANSFER', 'PAY') AND (nvl(EFTL.SOURCE_DOC_CATEGORY, 'N') != 'LON_CONTRACT_REPAYMENT' OR (EFTL.SOURCE_DOC_CATEGORY = 'LON_CONTRACT_REPAYMENT' AND nvl(EFTL.TRANSFER_TYPE, 'N') != 'PAY'))
UNION ALL --ABS/ABN 资产转让收款确认 SELECT CBBA.BANK_ACCOUNT_ID, CAPR.RECEIPT_AMOUNT, CAPR.RECEIPT_DATE, '资产转让-收款' TYPE, (SELECT cas.project_Grade FROM CT_ABS_PRODUCT_STRUCTURE Cas WHERE cas.structure_id = capr.structure_id) bp_name, 'IN' DIRECTION FROM CT_ABS_PRODUCT CAP JOIN CT_ABS_PRODUCT_RECEIPT CAPR ON CAP.PRODUCT_ID = CAPR.PRODUCT_ID JOIN CT_ABS_BANK_ACCOUNT CBBA ON CBBA.ABS_BANK_ACCOUNT_ID = CAPR.ABS_BANK_ACCOUNT_ID WHERE CAP.DATA_CLASS = 'NORMAL' AND CAP.PRODUCT_STATUS IN ('APPROVED', 'PENDING') UNION ALL --ABS/ABN 回购 SELECT CAPB.BANK_ACCOUNT_ID, -CAPB.BUYBACK_AMOUNT, CAPB.BUYBACK_DATE, '回购-付款' TYPE, (SELECT cas.project_Grade FROM CT_ABS_PRODUCT_STRUCTURE Cas WHERE cas.structure_id = capb.structure_id) bp_name, 'OUT' DIRECTION FROM CT_ABS_PRODUCT_BUYBACK CAPB JOIN CT_ABS_PRODUCT CAP ON CAPB.PRODUCT_ID = CAP.PRODUCT_ID WHERE CAP.DATA_CLASS = 'NORMAL' AND CAP.BUYBACK_STATUS = 'APPROVED' UNION ALL --其他发债收款 SELECT CABA.BANK_ACCOUNT_ID, CAP.ISSUE_AMOUNT, CAP.DUE_DATE_BEGIN, '其他发债-收款' TYPE, '' bp_name, 'IN' DIRECTION FROM CT_ABS_PRODUCT CAP JOIN CT_ABS_BANK_ACCOUNT CABA ON CAP.PRODUCT_ID = CABA.SOURCE_KEY AND CABA.SOURCE_TYPE = 'ABS_PRODUCT' AND CABA.BANK_ACCOUNT_TYPE = 'REG_REC_ACCOUNT' AND CABA.ACCOUNT_SOURCE_TYPE = 'OUR_ACCOUNT' WHERE CAP.DATA_CLASS = 'NORMAL' AND CAP.PRODUCT_STATUS IN ('APPROVED', 'PENDING')) p WHERE transaction_date < = #{balanceDate} AND (((SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date < = #{balanceDate} AND bank_account_id = p.bank_account_id) IS NULL) OR (((SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date < = #{balanceDate} AND bank_account_id = p.bank_account_id) IS NOT NULL AND transaction_date > (SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date < = #{balanceDate} AND bank_account_id = p.bank_account_id))))
and p.BANK_ACCOUNT_ID = #{bankAccountId}
union all select bank_account_id, case when other_amount>0 then other_amount else null end received_amount, case when other_amount>0 then null else other_amount end paid_amount, balance_date, account_balance, '手动调整差额' type, '' bp_name, balance_id, other_amount_description from cap_account_monthly_balance where 1=1
and bank_account_id = #{bankAccountId}

SELECT t.bank_name, t.currency_name, t.bank_id, t.company_id, t.currency, t.company_name, max(t.last_balance_date) last_balance_date, to_date(#{balanceDate},'YYYY-MM-DD') balanceDate, SUM(nvl(t.available_amount, 0)) available_amount, SUM(nvl(t.account_balance, 0)) account_balance, SUM(nvl(t.restricted_amount, 0)) restricted_amount, SUM(nvl(t.inv_unlimited_amount, 0)) inv_unlimited_amount, SUM(nvl(t.inv_limited_amount, 0)) inv_limited_amount FROM (SELECT cba.bank_branch_name, cba.bank_account_name, (SELECT currency_name FROM fnd_currency WHERE currency_code = cba.currency) currency_name, (SELECT fc.company_full_name FROM fnd_company fc WHERE fc.company_id = cba.company_id) company_name, cb.bank_name, cb.bank_id, cba.currency, cba.bank_account_num, cba.bank_account_type, (SELECT svb.meaning FROM sys_code_b sb, sys_code_value_b svb WHERE sb.code_id = svb.code_id AND svb.value = cba.bank_account_type AND svb.enabled_flag = 'Y' AND sb.code = 'CSH.BANK_ACCOUNT_TYPE') bank_account_type_desc, cba.company_id, cba.bank_account_id, nvl(cba.valid_flag, 'N') is_valid, (case when cba.valid_flag = 'Y' then '是' else '否' end) is_valid_desc, (case when cba.valid_flag = 'Y' then 0 else (nvl((SELECT account_balance FROM cap_account_monthly_balance cab WHERE cab.bank_account_id = cba.bank_account_id AND cab.balance_date = (SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date <= to_date(#{balanceDate},'YYYY-MM-DD') AND bank_account_id = cba.bank_account_id)), 0) + nvl(t.amount, 0)) end) available_amount, (case when cba.valid_flag = 'Y' then (nvl((SELECT account_balance FROM cap_account_monthly_balance cab WHERE cab.bank_account_id = cba.bank_account_id AND cab.balance_date = (SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date <= to_date(#{balanceDate},'YYYY-MM-DD') AND bank_account_id = cba.bank_account_id)), 0) + nvl(t.amount, 0)) else 0 end) restricted_amount, 0 investment_amount, --投资余额 (nvl((SELECT account_balance FROM cap_account_monthly_balance cab WHERE cab.bank_account_id = cba.bank_account_id AND cab.balance_date = (SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date <= to_date(#{balanceDate},'YYYY-MM-DD') AND bank_account_id = cba.bank_account_id)), 0) + nvl(t.amount, 0) + 0) account_balance, --账户余额 = 上期结存+本段期间收支 nvl(t.received_amount, 0) received_amount, nvl(t.paid_amount, 0) paid_amount, nvl((SELECT balance_status FROM cap_account_monthly_balance cab WHERE cab.bank_account_id = cba.bank_account_id AND cab.balance_date = (SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date >= to_date(#{balanceDate},'YYYY-MM-DD') AND bank_account_id = cba.bank_account_id) ), 'NOT') balance_status, nvl((SELECT other_amount FROM cap_account_monthly_balance cab WHERE cab.bank_account_id = cba.bank_account_id AND cab.balance_date = (SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date <= to_date(#{balanceDate},'YYYY-MM-DD')) AND bank_account_id = cba.bank_account_id), 0) other_amount, (SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE bank_account_id = cba.bank_account_id AND balance_status = 'FULL' AND balance_date <= to_date(#{balanceDate},'YYYY-MM-DD')) last_balance_date, to_date(#{balanceDate},'YYYY-MM-DD') balance_date, (SELECT MAX(balance_id) FROM cap_account_monthly_balance WHERE bank_account_id = cba.bank_account_id AND balance_date <= to_date(#{balanceDate},'YYYY-MM-DD')) balance_id, nvl(inv.unlimited_amount,0) inv_unlimited_amount, nvl(inv.limited_amount,0) inv_limited_amount FROM csh_bank_account cba,csh_bank cb, (SELECT SUM(nvl(transaction_amount, 0)) amount, SUM(nvl((case when direction = 'IN' then transaction_amount else 0 end), 0)) received_amount, SUM(nvl((case when direction = 'OUT' then -transaction_amount else 0 end), 0)) paid_amount, bank_account_id FROM ( --收款 SELECT CT.BANK_ACCOUNT_ID, CT.TRANSACTION_AMOUNT, CT.TRANSACTION_DATE, 'IN' DIRECTION FROM CSH_TRANSACTION CT WHERE CT.REVERSED_FLAG = 'N' AND CT.TRANSACTION_TYPE = 'RECEIPT' --退款 UNION ALL SELECT CT.BANK_ACCOUNT_ID, -CT.TRANSACTION_AMOUNT, CT.TRANSACTION_DATE, 'OUT' DIRECTION FROM CSH_TRANSACTION CT WHERE CT.REVERSED_FLAG = 'N' AND CT.TRANSACTION_TYPE = 'REFUND' UNION ALL --付款 SELECT CT.BANK_ACCOUNT_ID, -CT.TRANSACTION_AMOUNT, CT.TRANSACTION_DATE, 'OUT' DIRECTION FROM CSH_TRANSACTION CT WHERE CT.REVERSED_FLAG = 'N' AND CT.TRANSACTION_TYPE = 'PAYMENT' UNION ALL --融资收款 SELECT CLCBA.BANK_ACCOUNT_ID, LCW.DUE_AMOUNT, LCW.DUE_DATE, 'IN' DIRECTION FROM LON_CONTRACT_WITHDRAW LCW JOIN CT_LON_CONTRACT_BANK_ACCOUNT CLCBA ON CLCBA.BANK_ACCOUNT_TYPE = 'WITHDRAWAL_ACCOUNT' AND CLCBA.CONTRACT_ID = LCW.CONTRACT_ID WHERE LCW.DATA_CLASS = 'NORMAL' AND LCW.WITHDRAW_STATUS IN ('APPROVED', 'PENDING') UNION ALL --融资还款 SELECT LCRN.BANK_ACCOUNT_ID, -LCRN.DUE_AMOUNT, LCRN.DUE_DATE, 'OUT' DIRECTION FROM LON_CONTRACT_WITHDRAW LCW JOIN LON_CONTRACT_REPAYMENT_LN LCRN ON LCW.WITHDRAW_ID = LCRN.WITHDRAW_ID WHERE LCW.DATA_CLASS = 'NORMAL' UNION ALL --资金调拨 拨出 SELECT EFTL.OUT_BANK_ACCOUNT_ID, -EFTL.ACTUAL_PAY_AMOUNT, EFTL.ACTUAL_PAY_DATE, 'OUT' DIRECTION FROM EFT_FUND_TRANSFER_LIST EFTL WHERE EFTL.TRANSFER_STATUS = 'CONFIRM' AND EFTL.DATA_CLASS = 'NORMAL' AND EFTL.TRANSFER_TYPE IN ('TRANSFER', 'PAY') AND ( nvl(EFTL.SOURCE_DOC_CATEGORY,'N')!='LON_CONTRACT_REPAYMENT' OR ( EFTL.SOURCE_DOC_CATEGORY='LON_CONTRACT_REPAYMENT' AND nvl(EFTL.TRANSFER_TYPE,'N')!='PAY'))
UNION ALL --资金调拨 拨入 SELECT EFTL.IN_BANK_ACCOUNT_ID, EFTL.ACTUAL_PAY_AMOUNT, EFTL.ACTUAL_PAY_DATE, 'IN' DIRECTION FROM EFT_FUND_TRANSFER_LIST EFTL WHERE EFTL.TRANSFER_STATUS = 'CONFIRM' AND EFTL.DATA_CLASS = 'NORMAL' AND EFTL.TRANSFER_TYPE IN ('TRANSFER', 'PAY') AND ( nvl(EFTL.SOURCE_DOC_CATEGORY,'N')!='LON_CONTRACT_REPAYMENT' OR ( EFTL.SOURCE_DOC_CATEGORY='LON_CONTRACT_REPAYMENT' AND nvl(EFTL.TRANSFER_TYPE,'N')!='PAY'))
UNION ALL --ABS/ABN 资产转让收款确认 SELECT CBBA.BANK_ACCOUNT_ID, CAPR.RECEIPT_AMOUNT, CAPR.RECEIPT_DATE, 'IN' DIRECTION FROM CT_ABS_PRODUCT CAP JOIN CT_ABS_PRODUCT_RECEIPT CAPR ON CAP.PRODUCT_ID = CAPR.PRODUCT_ID JOIN CT_ABS_BANK_ACCOUNT CBBA ON CBBA.ABS_BANK_ACCOUNT_ID = CAPR.ABS_BANK_ACCOUNT_ID WHERE CAP.DATA_CLASS = 'NORMAL' AND CAP.PRODUCT_STATUS IN ('APPROVED', 'PENDING') UNION ALL --ABS/ABN 回购 SELECT CAPB.BANK_ACCOUNT_ID, -CAPB.BUYBACK_AMOUNT, CAPB.BUYBACK_DATE, 'OUT' DIRECTION FROM CT_ABS_PRODUCT_BUYBACK CAPB JOIN CT_ABS_PRODUCT CAP ON CAPB.PRODUCT_ID = CAP.PRODUCT_ID WHERE CAP.DATA_CLASS = 'NORMAL' AND CAP.BUYBACK_STATUS = 'APPROVED' UNION ALL --其他发债收款 SELECT CABA.BANK_ACCOUNT_ID, CAP.ISSUE_AMOUNT, CAP.DUE_DATE_BEGIN, 'IN' DIRECTION FROM CT_ABS_PRODUCT CAP JOIN CT_ABS_BANK_ACCOUNT CABA ON CAP.PRODUCT_ID = CABA.SOURCE_KEY AND CABA.SOURCE_TYPE = 'ABS_PRODUCT' AND CABA.BANK_ACCOUNT_TYPE = 'REG_REC_ACCOUNT' AND CABA.ACCOUNT_SOURCE_TYPE = 'OUR_ACCOUNT' WHERE CAP.DATA_CLASS = 'NORMAL' AND CAP.PRODUCT_STATUS IN ('APPROVED', 'PENDING')) p WHERE transaction_date <= to_date(#{balanceDate},'YYYY-MM-DD') AND (((SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date <= to_date(#{balanceDate},'YYYY-MM-DD') AND bank_account_id = p.bank_account_id) IS NULL) OR (((SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date <= to_date(#{balanceDate},'YYYY-MM-DD') AND bank_account_id = p.bank_account_id) IS NOT NULL AND transaction_date > (SELECT MAX(balance_date) FROM cap_account_monthly_balance WHERE balance_date <= to_date(#{balanceDate},'YYYY-MM-DD') AND bank_account_id = p.bank_account_id)))) GROUP BY bank_account_id) t, ( select ifp.bank_account_id, sum((case when ifp.is_limited = 'Y' then (ifp.purchased_amount-ifp.redeemed_amount) else 0 end)) unlimited_amount, sum((case when nvl(ifp.is_limited,'N') = 'N' then(ifp.purchased_amount-ifp.redeemed_amount) else 0 end)) limited_amount from inv_finance_purchase ifp group by ifp.bank_account_id) inv
where t.bank_account_id(+) = cba.bank_account_id and cba.bank_id = cb.bank_id AND inv.bank_account_id(+)= cba.bank_account_id ) t where 1=1
and t.bank_id = #{bankId}
and t.currency=#{currency}
and t.company_id=#{companyId}
and t.bank_name like '%'||#{bankName}||'%'
GROUP BY t.bank_name, t.currency_name, t.bank_id, t.company_id, t.currency, t.company_name, to_date(#{balanceDate},'YYYY-MM-DD')

select ca.*
from cap_account_monthly_balance ca
where ca.balance_date = (select min(balance_date) from cap_account_monthly_balance where balance_date < #{balanceDate}
and bank_account_id = ca.bank_account_id and balance_status = 'NOT')
  and ca.bank_account_id = #{bankAccountId}
  order by ca.period desc

select ct.transaction_date,ct.transaction_type,ct.transaction_amount,
ct.bp_id,hbm.bp_name,ct.payment_method,sc.description type, cwo.cf_item flow
from csh_transaction ct
left join (select cwo.cf_item cf_item,cwo.csh_transaction_id from csh_write_off cwo GROUP BY
cwo.csh_transaction_id,cwo.cf_item) cwo on cwo.csh_transaction_id = ct.transaction_id
LEFT JOIN hls_bp_master hbm
on ct.bp_id = hbm.bp_id
LEFT JOIN
(SELECT DESCRIPTION, document_type, business_type
FROM hls_document_type
WHERE document_category = 'CSH_TRANSACTION')sc
on sc.document_type = ct.transaction_type and sc.business_type = ct.business_type
where ct.bank_account_id = #{bankAccountId}
and ct.transaction_type in ('RECEIPT')

    and ct.transaction_date = #{period}


    and ct.transaction_date >= #{start}


    and ct.transaction_date < #{end}


    and ct.transaction_date <= #{balanceDate}


    and ct.transaction_date > #{lastBalanceDate}


union all

select ct.transaction_date,ct.transaction_type,cw.csh_write_off_amount,
ct.bp_id,hbm.bp_name,ct.payment_method,sc.description type, ''
from csh_transaction ct
left join csh_write_off cw on cw.csh_transaction_id = ct.transaction_id
LEFT JOIN hls_bp_master hbm
on ct.bp_id = hbm.bp_id
LEFT JOIN
(SELECT DESCRIPTION, document_type, business_type
FROM hls_document_type
WHERE document_category = 'CSH_TRANSACTION')sc
on sc.document_type = ct.transaction_type and sc.business_type = ct.business_type
where ct.bank_account_id = #{bankAccountId}
and ct.transaction_type in ('PAYMENT','REFUND')

    and ct.transaction_date = #{period}


    and ct.transaction_date>= #{start}


    and  ct.transaction_date < #{end}


    and ct.transaction_date <= #{balanceDate}


    and ct.transaction_date > #{lastBalanceDate}


union all

select ln.due_date,'LON_PAYMENT',ln.due_amount,
0,lcr.received_bp_name,'','融资还款',''
from lon_contract_repayment_ln ln,
lon_contract_repayment lcr
where ln.repayment_id = lcr.repayment_id

    and ln.due_date = #{period}


    and ln.due_date >= #{start}


    and ln.due_date < #{end}


    and ln.due_date <= #{balanceDate}


    and ln.due_date > #{lastBalanceDate}

and ln.bank_account_id = #{bankAccountId}

-- 未做提款从计划取，做了提款从提款取

union all

select lcw.due_date,'LON_WITHDRAW',lcw.due_amount,
lc.credit_bp_id,hbm.bp_name,'','',''
from lon_contract_withdraw lcw,
lon_contract lc
left join hls_bp_master hbm
on hbm.bp_id = lc.credit_bp_id
where lcw.contract_id = lc.contract_id
and lcw.data_class = 'NORMAL'
and lcw.withdraw_status in ('APPROVED','PENDING')
and lc.lon_company_id not in (265,266)

    and lcw.due_date = #{period}
    and lcw.due_date <= sysdate


    and lcw.due_date >= #{start}


    and lcw.due_date < #{end}


    and lcw.due_date <= #{balanceDate}


    and lcw.due_date > #{lastBalanceDate}

and lc.withdraw_bank_account_id = #{bankAccountId}

union all

select pl.withdraw_plan_date,'LON_WITHDRAW',pl.withdraw_plan_amount,lc.credit_bp_id,hbm.bp_name,'','',''
from ct_lon_contract_withdraw_plan pl,
lon_contract lc
left join hls_bp_master hbm
on hbm.bp_id = lc.credit_bp_id
where pl.contract_id = lc.contract_id
and lc.data_class = 'NORMAL'
and lc.contract_status in ('APPROVED','PENDING')
and lc.lon_company_id not in (265,266)
and (select count(1) from lon_contract_withdraw lcw where lcw.contract_id = lc.contract_id
and lcw.data_class = 'NORMAL' and lcw.withdraw_status in ('APPROVED','PENDING')) = 0

    and pl.withdraw_plan_date = #{period}
    and pl.withdraw_plan_date <= sysdate


    and pl.withdraw_plan_date >= #{start}


    and pl.withdraw_plan_date < #{end}


    and pl.withdraw_plan_date <= #{balanceDate}


    and pl.withdraw_plan_date > #{lastBalanceDate}

and lc.withdraw_bank_account_id = #{bankAccountId}

SELECT nvl(sum(w.amount) ,0)withdraw_amount FROM ( select cfp.apply_amount-nvl(lon.withdraw_plan_amount,0)-nvl(lc.due_amount,0) amount from cap_financing_plan cfp left join ( select cp.plan_id,cp.withdraw_plan_amount from lon_contract lc, ct_lon_contract_withdraw_plan cp where lc.contract_id = cp.contract_id and lc.data_class = 'NORMAL' and lc.contract_status in ('APPROVED','PENDING') and lc.lon_company_id = #{request.companyId} )lon on cfp.plan_id = lon.plan_id
left join ( select cp.plan_id,cp.due_amount from lon_contract lc, lon_contract_withdraw cp where lc.contract_id = cp.contract_id and lc.data_class = 'NORMAL' and lc.lon_company_id = #{request.companyId} )lc on cfp.plan_id = lc.plan_id where cfp.period >= to_char(sysdate,'yyyy-mm') AND cfp.period <= to_char(#{period},'yyyy-mm') AND cfp.confirm_status = 'NOT' AND cfp.company_id = #{request.companyId}
union all
SELECT sum( cp.withdraw_plan_amount ) amount FROM ct_lon_contract_withdraw_plan cp, lon_contract lc WHERE cp.contract_id = lc.contract_id AND ( SELECT count( 1 ) FROM lon_contract_withdraw lcw WHERE lcw.contract_id = lc.contract_id AND lcw.data_class = 'NORMAL' ) = 0 AND lc.lon_company_id = #{request.companyId} AND lc.withdraw_bank_account_id IS NULL AND lc.data_class = 'NORMAL' AND cp.withdraw_plan_date >= to_charnow( ), 'YYYY-MM-DD') AND cp.withdraw_plan_date <= #{period}
UNION ALL
SELECT sum( lcw.due_amount ) amount FROM lon_contract_withdraw lcw, lon_contract lc WHERE lcw.contract_id = lc.contract_id AND lc.lon_company_id = #{request.companyId} AND lcw.data_class = 'NORMAL' AND lcw.due_date >= to_charnow( ), 'YYYY-MM-DD') AND lcw.due_date <= #{period} AND lc.withdraw_bank_account_id IS NULL )w

select nvl(sum(r.amount) ,0)repayment_amount, sum(r.other_amount) lon_other_amount
from (
    SELECT SUM((case when lcr.cf_item = 301 then lcr.planned_due_amount else 0 end)) amount,
           SUM((case when lcr.cf_item = 301 then 0 else lcr.planned_due_amount end)) other_amount
      FROM lon_contract_repayment lcr, lon_contract lc
     WHERE lcr.contract_id = lc.contract_id
       AND lc.lon_company_id = #{request.companyId}
       AND lcr.planned_due_date >= #{startPeriod}
        AND lcr.planned_due_date <= #{period}
        AND lcr.write_off_flag != 'FULL'
        AND lc.repayment_bank_account_id IS NULL UNION ALL
      SELECT SUM((case when re.cf_item = 301 then re.repayment_amount else 0 end)) amount,
             SUM((case when re.cf_item = 301 then 0 else re.repayment_amount end)) other_amount
        FROM ct_lon_contract_repayment_plan re, lon_contract lc
       WHERE re.contract_id = lc.contract_id
         AND (SELECT COUNT(1)
                FROM lon_contract_repayment lcr
               WHERE lcr.contract_id = lc.contract_id) = 0
         AND lc.lon_company_id = #{request.companyId}
         AND lc.data_class = 'NORMAL'
         AND lc.contract_status IN ('APPROVED', 'PENDING')
         AND re.repayment_date >= #{startPeriod}
         AND re.repayment_date <= #{period}
         AND lc.repayment_bank_account_id IS NULL
) r

-- 未创建过小合同的大合同 SELECT fp.project_id, fp.contract_name contract_name, fqc.due_date, sum( CASE WHEN ( fqc.cf_item = 40 ) THEN fqc.due_amount - fqc.write_off_amount ELSE 0 END ) amount, sum( CASE WHEN ( fqc.cf_item = 51 ) THEN fqc.due_amount - fqc.write_off_amount ELSE 0 END ) deposit_amount, sum( CASE WHEN ( fqc.quotation_cashflow_id = c.quotation_cashflow_id ) THEN cc.due_amount ELSE 0 END ) deposit_amount_out, sum( CASE WHEN( fqc.cf_item = 54 ) THEN fqc.due_amount - fqc.write_off_amount ELSE 0 END ) due_amount, sum( CASE WHEN ( fqc.cf_item = 55 ) THEN fqc.due_amount - fqc.write_off_amount ELSE 0 END ) use_amount, sum( CASE WHEN ( fqc.cf_item = 56 ) THEN fqc.due_amount - fqc.write_off_amount ELSE 0 END ) capital_amount, sum( CASE WHEN ( fqc.cf_item = 57 ) THEN fqc.due_amount - fqc.write_off_amount ELSE 0 END ) service_amount, sum( CASE WHEN ( fqc.cf_item = 58 ) THEN fqc.due_amount - fqc.write_off_amount ELSE 0 END ) other_amount, sum( CASE WHEN ( fqc.cf_item = 59 ) THEN fqc.due_amount - fqc.write_off_amount ELSE 0 END ) grace_amount FROM fct_project fp, fct_quotation_cashflow fqc, fct_project_quotation fpq left join fct_quotation_cashflow c on c.quotation_id = fpq.quotataion_id and to_char(c.due_date,'YYYY-MM-DD') = to_char(fpq.rate_valid_to,'YYYY-MM-DD') and c.cf_item = 54 left join fct_quotation_cashflow cc on cc.quotation_id = fpq.quotataion_id and cc.cf_item = 51 WHERE fp.project_id = fpq.project_id AND fqc.quotation_id = fpq.quotataion_id AND fp.contract_status != 'CANCEL' AND fp.data_class = 'VIRTUAL_CON' AND fp.data_type NOT IN ( 'CHANGE_REQ', 'HISTORY' ) AND ( SELECT count( 1 ) FROM fct_contract fc WHERE fc.project_id = fp.project_id) = 0 AND fqc.due_date >= to_char(now( ), 'YYYY-MM-DD') AND fqc.due_date <= #{period} AND fqc.cf_status = 'RELEASE'
AND fp.fct_payment_account_id = #{bankAccountId}
AND fp.fct_payment_account_id is null
GROUP BY fp.project_id, fp.project_name, fqc.due_date
UNION ALL -- 小合同现金流 SELECT fc.contract_id, fc.contract_name, fqc.due_date, sum( CASE WHEN ( fqc.cf_item = 40 ) THEN fqc.due_amount - fqc.write_off_amount ELSE 0 END ) amount, sum( CASE WHEN ( fqc.cf_item = 51 ) THEN fqc.due_amount - fqc.write_off_amount ELSE 0 END ) deposit_amount, sum( CASE WHEN ( fqc.quotation_cashflow_id = c.quotation_cashflow_id ) THEN cc.due_amount - nvl(e.received_amount,0) ELSE 0 END ) deposit_amount_out, sum( CASE WHEN ( fqc.cf_item = 54 ) THEN fqc.due_amount - fqc.write_off_amount ELSE 0 END ) due_amount, sum( CASE WHEN ( fqc.cf_item = 55 ) THEN fqc.due_amount - fqc.write_off_amount ELSE 0 END ) use_amount, sum( CASE WHEN ( fqc.cf_item = 56 ) THEN fqc.due_amount - fqc.write_off_amount ELSE 0 END ) capital_amount, sum( CASE WHEN ( fqc.cf_item = 57 ) THEN fqc.due_amount - fqc.write_off_amount ELSE 0 END ) service_amount, sum( CASE WHEN ( fqc.cf_item = 58 )THEN fqc.due_amount - fqc.write_off_amount ELSE 0 END ) other_amount, sum( CASE WHEN( fqc.cf_item = 59 ) THEN fqc.due_amount - fqc.write_off_amount ELSE 0 END ) grace_amount FROM fct_quotation_cashflow fqc, fct_contract fc left join fct_quotation_cashflow c on c.contract_id = fc.contract_id and to_char(c.due_date,'YYYY-MM-DD') = to_char(fc.rate_valid_to,'YYYY-MM-DD') and c.cf_item = 54 left join fct_quotation_cashflow cc on cc.contract_id = fc.contract_id and cc.cf_item = 51 left join fct_quotation_cashflow e on e.contract_id = fc.contract_id and cc.cf_item = 52 WHERE fc.contract_id = fqc.contract_id -- AND fqc.due_date >= to_char(now( ), 'YYYY-MM-DD') AND fqc.due_date >= #{startPeriod} AND fqc.due_date <= #{period}
AND fc.fct_payment_account_id = #{bankAccountId}
AND fc.fct_payment_account_id is null
AND fqc.write_off_flag != 'FULL' AND fc.data_class = 'NORMAL' AND fqc.cf_status = 'RELEASE' GROUP BY fc.contract_id, fc.contract_name, fqc.due_date
-- 投放计划 UNION ALL
SELECT ln.project_id, fp.project_name, ln.pay_date, ln.apply_investment_amount,0,0,0,0,0,0,0,0 FROM cap_capital_investment_plan_ln ln left join fct_project fp on fp.project_id = ln.project_id WHERE ln.execute_status NOT IN ( 'CANCEL' ) AND ln.company_id = 264 AND ( SELECT count( 1 ) FROM fct_project fp WHERE fp.ref_project_id = ln.project_id AND data_class = 'VIRTUAL_CON' AND fp.contract_status NOT IN ( 'CANCEL' ) ) = 0 AND ln.pay_date >= #{startPeriod} AND ln.pay_date <= #{period}
UNION ALL SELECT w.contract_id, fc.contract_name, w.write_off_date, sum( CASE WHEN ( w.cf_item = 40 ) THEN w.csh_write_off_amount ELSE 0 END ) amount, sum( CASE WHEN ( w.cf_item = 51 ) THEN w.csh_write_off_amount ELSE 0 END ) deposit_amount, sum( CASE WHEN ( w.cf_item = 52 ) THEN w.csh_write_off_amount ELSE 0 END ) deposit_amount_out, sum( CASE WHEN ( w.cf_item = 54 ) THEN w.csh_write_off_amount ELSE 0 END ) due_amount, sum( CASE WHEN ( w.cf_item = 55 ) THEN w.csh_write_off_amount ELSE 0 END ) use_amount, sum( CASE WHEN ( w.cf_item = 56 ) THEN w.csh_write_off_amount ELSE 0 END ) capital_amount, sum( CASE WHEN ( w.cf_item = 57 ) THEN w.csh_write_off_amount ELSE 0 END ) service_amount, sum( CASE WHEN ( w.cf_item = 58 ) THEN w.csh_write_off_amount ELSE 0 END ) other_amount, sum( CASE WHEN ( w.cf_item = 59 ) THEN w.csh_write_off_amount ELSE 0 END ) grace_amount FROM csh_write_off w LEFT JOIN fct_contract fc ON fc.contract_id = w.contract_id AND fc.data_class = 'NORMAL' left join csh_transaction t on t.transaction_id = w.csh_transaction_id WHERE w.write_off_date >= #{startPeriod} AND w.write_off_date < to_char(now( ), 'YYYY-MM-DD') AND w.write_off_date <= #{period} AND w.write_off_doc_category = 'FCT_CONTRACT' AND w.reversed_flag NOT IN ( 'R' ) AND w.write_off_type not in ('DEPOSIT_CREDIT')
AND t.bank_account_id = #{bankAccountId}
AND t.bank_account_id is null
GROUP BY w.contract_id, fc.contract_name, w.write_off_date
-- 反冲 UNION ALL SELECT w.contract_id, fc.contract_name, w.write_off_date, sum( CASE WHEN ( w.cf_item = 40 ) THEN w.csh_write_off_amount ELSE 0 END ) amount, sum( CASE WHEN ( w.cf_item = 51 ) THEN w.csh_write_off_amount ELSE 0 END ) deposit_amount, sum( CASE WHEN ( w.cf_item = 52 ) THEN w.csh_write_off_amount ELSE 0 END ) deposit_amount_out, sum( CASE WHEN ( w.cf_item = 54 ) THEN w.csh_write_off_amount ELSE 0 END ) due_amount, sum( CASE WHEN ( w.cf_item = 55 ) THEN w.csh_write_off_amount ELSE 0 END ) use_amount, sum( CASE WHEN ( w.cf_item = 56 ) THEN w.csh_write_off_amount ELSE 0 END ) capital_amount, sum( CASE WHEN ( w.cf_item = 57 ) THEN w.csh_write_off_amount ELSE 0 END ) service_amount, sum( CASE WHEN ( w.cf_item = 58 ) THEN w.csh_write_off_amount ELSE 0 END ) other_amount, sum( CASE WHEN ( w.cf_item = 59 ) THEN w.csh_write_off_amount ELSE 0 END ) grace_amount FROM csh_write_off w LEFT JOIN fct_contract fc ON fc.contract_id = w.contract_id AND fc.data_class = 'NORMAL' left join csh_transaction t on t.transaction_id = w.csh_transaction_id WHERE w.write_off_date >= #{startPeriod} AND w.write_off_date < to_char(now( ), 'YYYY-MM-DD') AND w.write_off_date <= #{period} AND w.write_off_doc_category = 'FCT_CONTRACT' AND w.reversed_flag = 'R' AND w.write_off_type not in ('DEPOSIT_CREDIT')
AND t.bank_account_id = #{bankAccountId}
AND t.bank_account_id is null
GROUP BY w.contract_id, fc.contract_name, w.write_off_date
ORDER BY due_date

select 'WITHDRAW_PLAN' type,cfp.plan_id contract_id,cfp.plan_name contract_name, cfp.period period,cfp.apply_amount-nvl(lon.withdraw_plan_amount,0)-nvl(lc.due_amount,0) withdraw_amount, 0 repayment_amount,0 interest_amount,0 charge_fee,0 consulting_fee,0 deposit,0 consignment_sales_fee,0 collocation_fee,0 management_fee,0 other_amount from cap_financing_plan cfp left join ( select cp.plan_id,sum(nvl(cp.withdraw_plan_amount,0))withdraw_plan_amount from lon_contract lc, ct_lon_contract_withdraw_plan cp where lc.contract_id = cp.contract_id and lc.contract_status in ('APPROVED','PENDING') and lc.lon_company_id = #{request.companyId} GROUP BY cp.plan_id )lon on cfp.plan_id = lon.plan_id
left join ( select cp.plan_id,sum(nvl(cp.due_amount,0))due_amount from lon_contract lc, lon_contract_withdraw cp where lc.contract_id = cp.contract_id and lc.data_class = 'NORMAL' and lc.lon_company_id = #{request.companyId} GROUP BY cp.plan_id )lc on cfp.plan_id = lc.plan_id
where cfp.period <= to_char(#{period},'yyyy-mm') and cfp.period >= to_char(sysdate,'yyyy-mm') and cfp.confirm_status = 'NOT' and cfp.company_id = #{request.companyId} union all
-- 融资还款（预测） select 'REPAYMENT' type,lc.contract_id,lc.contract_name, to_char(rp.repayment_date,'YYYY-MM-DD') period,0 withdraw_amount,sum(case when(rp.cf_item = 301) then rp.repayment_amount else 0 end)repayment_amount,sum(case when (rp.cf_item = 302) then rp.repayment_amount else 0 end)interest_amount, sum(case when (rp.cf_item = 303) then rp.repayment_amount else 0 end)charge_fee,sum(case when (rp.cf_item = 304) then rp.repayment_amount else 0 end)consulting_fee,sum(case when (rp.cf_item = 305) then rp.repayment_amount else 0 end)deposit, sum(case when (rp.cf_item = 306) then rp.repayment_amount else 0 end)consignment_sales_fee,sum(case when (rp.cf_item = 307) then rp.repayment_amount else 0 end)collocation_fee,sum(case when (rp.cf_item = 308) then rp.repayment_amount else 0 end) management_fee, sum(case when (rp.cf_item = 309) then rp.repayment_amount else 0 end)other_amount from lon_contract lc, ct_lon_contract_repayment_plan rp where lc.contract_id = rp.contract_id and (select count(1) from lon_contract_repayment lcr where lcr.contract_id = lc.contract_id) = 0 and lc.lon_company_id = #{request.companyId} and lc.data_class = 'NORMAL' and lc.contract_status in ('APPROVED','PENDING') and rp.repayment_date >= to_char(now( ), 'YYYY-MM-DD')
and lc.repayment_bank_account_id = #{bankAccountId}
AND lc.repayment_bank_account_id is null
and rp.repayment_date <= #{period} group by lc.contract_id,lc.contract_name,rp.repayment_date
union all
select 'REPAYMENT',lc.contract_id,lc.contract_name, to_char(rp.planned_due_date,'YYYY-MM-DD'),0,sum(case when (rp.cf_item = 301) then rp.planned_due_amount else 0 end)repayment_amount,sum(case when (rp.cf_item = 302) then rp.planned_due_amount else 0 end)interest_amount, sum(case when (rp.cf_item = 303) then rp.planned_due_amount else 0 end)charge_fee,sum(case when (rp.cf_item = 304) then rp.planned_due_amount else 0 end)consulting_fee,sum(case when (rp.cf_item = 305) then rp.planned_due_amount else 0 end) deposit, sum(case when (rp.cf_item = 306) then rp.planned_due_amount else 0 end)consignment_sales_fee,sum(case when (rp.cf_item = 307) then rp.planned_due_amount else 0 end)collocation_fee,sum(case when (rp.cf_item = 308) then rp.planned_due_amount else 0 end) management_fee, sum(case when (rp.cf_item = 309) then rp.planned_due_amount else 0 end)other_amount from lon_contract lc, lon_contract_repayment rp where lc.contract_id = rp.contract_id and lc.lon_company_id = #{request.companyId}
and lc.repayment_bank_account_id = #{bankAccountId}
AND lc.repayment_bank_account_id is null
and rp.planned_due_date >= #{startPeriod} and rp.planned_due_date <= #{period} and rp.write_off_flag = 'NOT' group by lc.contract_id,lc.contract_name,rp.planned_due_date
union all -- 融资还款历史 SELECT 'REPAYMENT', re.contract_id, lc.contract_name, to_char( ln.due_date, 'YYYY-MM-DD' ), 0, sum( CASE WHEN ( re.cf_item = 301 ) THEN ln.due_amount ELSE 0 END ) repayment_amount, sum( CASE WHEN ( re.cf_item = 302 ) THEN ln.due_amount ELSE 0 END ) interest_amount, sum( CASE WHEN ( re.cf_item = 303 ) THEN ln.due_amount ELSE 0 END ) charge_fee, sum( CASE WHEN ( re.cf_item = 304 ) THEN ln.due_amount ELSE 0 END ) consulting_fee, sum( CASE WHEN ( re.cf_item = 305 ) THEN ln.due_amount ELSE 0 END ) deposit, sum( CASE WHEN ( re.cf_item = 306 ) THEN ln.due_amount ELSE 0 END ) consignment_sales_fee, sum( CASE WHEN ( re.cf_item = 307 ) THEN ln.due_amount ELSE 0 END ) collocation_fee, sum( CASE WHEN ( re.cf_item = 308 ) THEN ln.due_amount ELSE 0 END ) management_fee, sum( CASE WHEN ( re.cf_item = 309 ) THEN ln.due_amount ELSE 0 END ) other_amount FROM lon_contract_repayment_ln ln, lon_contract_repayment re LEFT JOIN lon_contract lc ON lc.contract_id = re.contract_id AND lc.data_class = 'NORMAL' WHERE ln.repayment_id = re.repayment_id AND ln.due_date>= #{startPeriod} AND ln.due_date < to_char(now( ), 'YYYY-MM-DD') AND ln.due_date <= #{period}
and ln.bank_account_id = #{bankAccountId}
AND ln.bank_account_id is null
GROUP BY re.contract_id, lc.contract_name, ln.due_date
union all
-- 融资提款(预测) select 'WITHDRAW',lc.contract_id,lc.contract_name, to_char(cp.withdraw_plan_date,'YYYY-MM-DD'),cp.withdraw_plan_amount,0,0,0,0,0,0,0,0,0 from lon_contract lc, ct_lon_contract_withdraw_plan cp where lc.contract_id = cp.contract_id and lc.company_id = #{request.companyId} and (select count(1) from lon_contract_withdraw lcw where lcw.contract_id = lc.contract_id and lcw.data_class = 'NORMAL') = 0 and cp.withdraw_plan_date >= to_char(now( ), 'YYYY-MM-DD') and cp.withdraw_plan_date <= #{period}
and lc.withdraw_bank_account_id = #{bankAccountId}
AND lc.withdraw_bank_account_id is null
union all select 'WITHDRAW',lc.contract_id,lc.contract_name, to_char(lcw.due_date,'YYYY-MM-DD'),lcw.due_amount,0,0,0,0,0,0,0,0,0 from lon_contract lc, lon_contract_withdraw lcw where lc.contract_id = lcw.contract_id and lc.company_id = #{request.companyId} and lcw.data_class = 'NORMAL' and lcw.write_off_flag = 'NOT' and lcw.due_date >= to_char(now( ), 'YYYY-MM-DD') and lcw.due_date <= #{period}
and lc.withdraw_bank_account_id = #{bankAccountId}
AND lc.withdraw_bank_account_id is null
union all select 'WITHDRAW',lc.contract_id,lc.contract_name, to_char(lcw.due_date,'YYYY-MM-DD'),lcw.write_off_amount,0,0,0,0,0,0,0,0,0 from lon_contract lc, lon_contract_withdraw lcw where lc.contract_id = lcw.contract_id and lc.company_id = #{request.companyId} and lcw.data_class = 'NORMAL' and lcw.write_off_flag not in ('NOT') and lcw.due_date >= #{startPeriod} -- and lcw.due_date < to_char(now( ), 'YYYY-MM-DD') and lcw.due_date <= #{period}
and lc.withdraw_bank_account_id = #{bankAccountId}
AND lc.withdraw_bank_account_id is null

select sum(if((cf.due_date >=#{period} and cf.due_date < DATE_ADD(#{period},INTERVAL 1 WEEK)),cf.principal,0))first_week, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 1 WEEK) and cf.due_date < DATE_ADD(#{period},INTERVAL 2 WEEK)),cf.principal,0))second_week, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 2 WEEK) and cf.due_date < DATE_ADD(#{period},INTERVAL 3 WEEK)),cf.principal,0))third_week, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 3 WEEK) and cf.due_date < DATE_ADD(#{period},INTERVAL 4 WEEK)),cf.principal,0))fourth_week, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 1 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 2 MONTH)),cf.principal,0))second_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 2 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 3 MONTH)),cf.principal,0))third_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 3 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 4 MONTH)),cf.principal,0))fourth_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 4 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 5 MONTH)),cf.principal,0))fifth_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 5 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 6 MONTH)),cf.principal,0))sixth_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 6 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 7 MONTH)),cf.principal,0))seventh_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 7 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 8 MONTH)),cf.principal,0))eighth_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 8 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 9 MONTH)),cf.principal,0))ninth_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 9 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 10 MONTH)),cf.principal,0))tenth_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 10 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 11 MONTH)),cf.principal,0))eleventh_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 11 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 12 MONTH)),cf.principal,0))twelfth_month, sum(if((cf.due_date >=#{period} and cf.due_date < DATE_ADD(#{period},INTERVAL 12 MONTH)),cf.principal,0))all_month from con_contract_cashflow cf left join con_contract cc on cf.contract_id = cc.contract_id where 1=1
and cc.business_type = #{businessType}
and cc.data_class = 'NORMAL' and cf.cf_item = 1

select sum(if((cf.due_date >=#{period} and cf.due_date < DATE_ADD(#{period},INTERVAL 1 WEEK)),cf.due_amount,0))first_week, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 1 WEEK) and cf.due_date < DATE_ADD(#{period},INTERVAL 2 WEEK)),cf.due_amount,0))second_week, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 2 WEEK) and cf.due_date < DATE_ADD(#{period},INTERVAL 3 WEEK)),cf.due_amount,0))third_week, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 3 WEEK) and cf.due_date < DATE_ADD(#{period},INTERVAL 4 WEEK)),cf.due_amount,0))fourth_week, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 1 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 2 MONTH)),cf.due_amount,0))second_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 2 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 3 MONTH)),cf.due_amount,0))third_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 3 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 4 MONTH)),cf.due_amount,0))fourth_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 4 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 5 MONTH)),cf.due_amount,0))fifth_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 5 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 6 MONTH)),cf.due_amount,0))sixth_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 6 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 7 MONTH)),cf.due_amount,0))seventh_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 7 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 8 MONTH)),cf.due_amount,0))eighth_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 8 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 9 MONTH)),cf.due_amount,0))ninth_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 9 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 10 MONTH)),cf.due_amount,0))tenth_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 10 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 11 MONTH)),cf.due_amount,0))eleventh_month, sum(if((cf.due_date >=DATE_ADD(#{period},INTERVAL 11 MONTH) and cf.due_date < DATE_ADD(#{period},INTERVAL 12 MONTH)),cf.due_amount,0))twelfth_month, sum(if((cf.due_date >=#{period} and cf.due_date < DATE_ADD(#{period},INTERVAL 12 MONTH)),cf.due_amount,0))all_month from fct_quotation_cashflow cf left join fct_contract fc on cf.contract_id = fc.contract_id where 1=1
and fc.business_type = #{businessType}
and fc.data_class = 'NORMAL' AND cf.cf_status = 'RELEASE' and cf.cf_item = 54

select sum(tab.due_amount)due_amount from ( select lcw.due_amount from lon_contract_withdraw lcw, lon_contract lc left join hls_bp_master hbm on hbm.bp_id = lc.credit_bp_id where lcw.contract_id = lc.contract_id and lcw.data_class = 'NORMAL' and lcw.withdraw_status in ('APPROVED','PENDING') and lc.lon_company_id not in (265,266) and to_char(lcw.due_date,'YYYY-MM-DD') = to_char(sysdate,'YYYY-MM-DD') and lc.withdraw_bank_account_id = #{bankAccountId}
union all
select pl.withdraw_plan_amount from ct_lon_contract_withdraw_plan pl, lon_contract lc left join hls_bp_master hbm on hbm.bp_id = lc.credit_bp_id where pl.contract_id = lc.contract_id and lc.data_class = 'NORMAL' and lc.contract_status in ('APPROVED','PENDING') and lc.lon_company_id not in (265,266) and (select count(1) from lon_contract_withdraw lcw where lcw.contract_id = lc.contract_id and lcw.data_class = 'NORMAL' and lcw.withdraw_status in ('APPROVED','PENDING')) = 0 and to_char(pl.withdraw_plan_date,'YYYY-MM-DD') = to_char(sysdate,'YYYY-MM-DD') and lc.withdraw_bank_account_id = #{bankAccountId} )tab

WITH ACTBA AS ( SELECT BANK_ACCOUNT_ID, BALANCE_DATE, ACCOUNT_BALANCE FROM ( SELECT -- ROW_NUMBER() OVER(PARTITION BY AB.BANK_ACCOUNT_ID ORDER BY AB.BALANCE_DATE DESC -- ) RN, IF ( @p = AB.BANK_ACCOUNT_ID, @rank := @rank + 1 ,@rank := 1 ) AS RN, @p := AB.BANK_ACCOUNT_ID as rank1, AB.BANK_ACCOUNT_ID, AB.BALANCE_DATE, AB.ACCOUNT_BALANCE FROM CAP_ACCOUNT_MONTHLY_BALANCE AB,(SELECT @p := NULL ,@rank := 0) r WHERE AB.BALANCE_DATE <=#{startPeriod}) WHERE RN = 1 ) SELECT CB.BANK_ID, CB.BANK_NAME, BAC.COMPANY_ID, FC.COMPANY_FULL_NAME COMPANY_NAME, BAC.CURRENCY, FU.CURRENCY_NAME, nvl(BAC.ACCOUNT_BALANCE,0) ACCOUNT_BALANCE, nvl(BAC.CON_PRI_INT_AMOUNT,0) CON_PRI_INT_AMOUNT, nvl(BAC.LON_WITHDRAW_AMOUNT,0) LON_WITHDRAW_AMOUNT, nvl(BAC.CON_OTHER_AMOUNT,0) CON_OTHER_AMOUNT, nvl(BAC.FUND_TRANSFER_AMOUNT,0) FUND_TRANSFER_AMOUNT, nvl(BAC.CON_REPAYMENT_AMOUNT,0) CON_REPAYMENT_AMOUNT , nvl(BAC.LON_REPAYMENT_AMOUNT,0) LON_REPAYMENT_AMOUNT, nvl(BAC.LON_FEE_AMOUNT,0) LON_FEE_AMOUNT, nvl(BAC.ACCOUNT_BALANCE,0) + nvl(BAC.CON_PRI_INT_AMOUNT,0) + nvl(BAC.LON_WITHDRAW_AMOUNT,0) + nvl(BAC.CON_OTHER_AMOUNT,0) + nvl(BAC.FUND_TRANSFER_AMOUNT,0) + nvl(BAC.CON_REPAYMENT_AMOUNT,0) + nvl(BAC.LON_REPAYMENT_AMOUNT,0) + nvl(BAC.LON_FEE_AMOUNT,0) PREDICTED_AMOUNT FROM CSH_BANK CB LEFT JOIN ( SELECT CBA.BANK_ID, CBA.COMPANY_ID, CBA.CURRENCY, SUM( CASE WHEN ACTB.BANK_ACCOUNT_ID IS NULL THEN nvl(ACTBA.ACCOUNT_BALANCE,0) ELSE nvl(ACTB.ACCOUNT_BALANCE,0) END) ACCOUNT_BALANCE, SUM(CLA.CON_PRI_INT_AMOUNT) CON_PRI_INT_AMOUNT, SUM(CLA.LON_WITHDRAW_AMOUNT) LON_WITHDRAW_AMOUNT, SUM(CLA.CON_OTHER_AMOUNT) CON_OTHER_AMOUNT, SUM(CLA.FUND_TRANSFER_AMOUNT) FUND_TRANSFER_AMOUNT, SUM(CLA.CON_REPAYMENT_AMOUNT) CON_REPAYMENT_AMOUNT , SUM(CLA.LON_REPAYMENT_AMOUNT) LON_REPAYMENT_AMOUNT, SUM(CLA.LON_FEE_AMOUNT) LON_FEE_AMOUNT FROM CSH_BANK_ACCOUNT CBA LEFT JOIN -- 账户最后维护余额和开始日期之间实际发生的数据 ( SELECT CADA.BANK_ACCOUNT_ID, nvl(SUM(ACTBA.ACCOUNT_BALANCE),0) + nvl(SUM(CADA.DUE_AMOUNT),0) ACCOUNT_BALANCE FROM ( ) CADA LEFT JOIN ACTBA ON CADA.BANK_ACCOUNT_ID=ACTBA.BANK_ACCOUNT_ID AND ACTBA.BALANCE_DATE< CADA.DUE_DATE WHERE #{endPeriod}>CADA.DUE_DATE GROUP BY CADA.BANK_ACCOUNT_ID) ACTB ON ACTB.BANK_ACCOUNT_ID=CBA.BANK_ACCOUNT_ID LEFT JOIN ACTBA ON ACTBA.BANK_ACCOUNT_ID=CBA.BANK_ACCOUNT_ID LEFT JOIN --日期之间的预测数据 ( SELECT FEAD.BANK_ACCOUNT_ID, SUM( CASE WHEN FEAD.BUSINESS_TYPE='CON_RECEIPT' AND ( FEAD.CF_ITEM=1 OR FEAD.CF_ITEM=54 OR FEAD.CF_ITEM=55) THEN FEAD.DUE_AMOUNT ELSE 0 END ) CON_PRI_INT_AMOUNT, SUM( CASE WHEN FEAD.BUSINESS_TYPE='LON_WITHDRAW' THEN FEAD.DUE_AMOUNT ELSE 0 END ) LON_WITHDRAW_AMOUNT, SUM( CASE WHEN FEAD.BUSINESS_TYPE='CON_RECEIPT' AND FEAD.CF_ITEM!=1 AND FEAD.CF_ITEM!=54 AND FEAD.CF_ITEM!=55 THEN FEAD.DUE_AMOUNT ELSE 0 END ) CON_OTHER_AMOUNT, SUM( CASE WHEN FEAD.BUSINESS_TYPE='FUND_TRANSFER' THEN FEAD.DUE_AMOUNT ELSE 0 END ) FUND_TRANSFER_AMOUNT, SUM( CASE WHEN FEAD.BUSINESS_TYPE='CON_REPAYMENT' THEN FEAD.DUE_AMOUNT ELSE 0 END ) CON_REPAYMENT_AMOUNT , SUM( CASE WHEN FEAD.BUSINESS_TYPE='LON_REPAYMENT' THEN FEAD.DUE_AMOUNT ELSE 0 END ) LON_REPAYMENT_AMOUNT, SUM( CASE WHEN FEAD.BUSINESS_TYPE='LON_FEE' THEN FEAD.DUE_AMOUNT ELSE 0 END ) LON_FEE_AMOUNT FROM (
) FEAD WHERE FEAD.DUE_DATE>=#{startPeriod} AND FEAD.DUE_DATE<=#{endPeriod} GROUP BY FEAD.BANK_ACCOUNT_ID ) CLA ON CLA.BANK_ACCOUNT_ID=CBA.BANK_ACCOUNT_ID WHERE 1=1 GROUP BY CBA.BANK_ID, CBA.COMPANY_ID, CBA.CURRENCY) BAC ON CB.BANK_ID=BAC.BANK_ID LEFT JOIN FND_COMPANY FC ON FC.COMPANY_ID=BAC.COMPANY_ID LEFT JOIN FND_CURRENCY FU ON FU.CURRENCY_CODE=BAC.CURRENCY WHERE 1=1
AND CB.BANK_NAME LIKE CONCAT(CONCAT('%',#{bankName}),'%')
AND BAC.CURRENCY = #{currency}
AND CB.BANK_ID = #{bankId}
AND BAC.COMPANY_ID = #{companyId}

WITH ACTBA AS ( SELECT BANK_ACCOUNT_ID, BALANCE_DATE, ACCOUNT_BALANCE FROM ( SELECT -- ROW_NUMBER() OVER(PARTITION BY AB.BANK_ACCOUNT_ID ORDER BY AB.BALANCE_DATE DESC -- ) RN, IF ( @p = AB.BANK_ACCOUNT_ID, @rank := @rank + 1 ,@rank := 1 ) AS RN, @p := AB.BANK_ACCOUNT_ID as rank1, AB.BANK_ACCOUNT_ID, AB.BALANCE_DATE, AB.ACCOUNT_BALANCE FROM CAP_ACCOUNT_MONTHLY_BALANCE AB,(SELECT @p := NULL ,@rank := 0) r WHERE AB.BALANCE_DATE<=#{startPeriod}) WHERE RN = 1 ) SELECT CBA.BANK_ACCOUNT_ID, CBA.BANK_ACCOUNT_NUM, CBA.BANK_ACCOUNT_NAME, CBA.BANK_BRANCH_NAME, CB.BANK_ID, CB.BANK_NAME, CASE WHEN ACTB.BANK_ACCOUNT_ID IS NULL THEN nvl(ACTBA.ACCOUNT_BALANCE,0) ELSE nvl(ACTB.ACCOUNT_BALANCE,0) END ACCOUNT_BALANCE, nvl(CLA.CON_PRI_INT_AMOUNT,0) CON_PRI_INT_AMOUNT, nvl(CLA.LON_WITHDRAW_AMOUNT,0) LON_WITHDRAW_AMOUNT, nvl(CLA.CON_OTHER_AMOUNT,0) CON_OTHER_AMOUNT, nvl(CLA.FUND_TRANSFER_AMOUNT,0) FUND_TRANSFER_AMOUNT, nvl(CLA.CON_REPAYMENT_AMOUNT,0) CON_REPAYMENT_AMOUNT , nvl(CLA.LON_REPAYMENT_AMOUNT,0) LON_REPAYMENT_AMOUNT, nvl(CLA.LON_FEE_AMOUNT,0) LON_FEE_AMOUNT, ( CASE WHEN ACTB.BANK_ACCOUNT_ID IS NULL THEN nvl(ACTBA.ACCOUNT_BALANCE,0) ELSE nvl(ACTB.ACCOUNT_BALANCE,0) END )+ nvl(CLA.CON_PRI_INT_AMOUNT,0) + nvl(CLA.LON_WITHDRAW_AMOUNT,0) + ifnull (CLA.CON_OTHER_AMOUNT,0) + nvl(CLA.FUND_TRANSFER_AMOUNT,0) + nvl(CLA.CON_REPAYMENT_AMOUNT,0) + nvl(CLA.LON_REPAYMENT_AMOUNT,0) + nvl(CLA.LON_FEE_AMOUNT,0) PREDICTED_AMOUNT FROM CSH_BANK_ACCOUNT CBA JOIN CSH_BANK CB ON CB.BANK_ID=CBA.BANK_ID LEFT JOIN -- 账户最后维护余额和开始日期之间实际发生的数据 ( SELECT CADA.BANK_ACCOUNT_ID, nvl(SUM(ACTBA.ACCOUNT_BALANCE),0) + nvl(SUM(CADA.DUE_AMOUNT),0) ACCOUNT_BALANCE FROM ( ) CADA LEFT JOIN ACTBA ON CADA.BANK_ACCOUNT_ID=ACTBA.BANK_ACCOUNT_ID AND ACTBA.BALANCE_DATE< CADA.DUE_DATE WHERE #{endPeriod}>CADA.DUE_DATE GROUP BY CADA.BANK_ACCOUNT_ID) ACTB ON ACTB.BANK_ACCOUNT_ID=CBA.BANK_ACCOUNT_ID LEFT JOIN ACTBA ON ACTBA.BANK_ACCOUNT_ID=CBA.BANK_ACCOUNT_ID LEFT JOIN --日期之间的预测数据 ( SELECT FEAD.BANK_ACCOUNT_ID, SUM( CASE WHEN FEAD.BUSINESS_TYPE='CON_RECEIPT' AND ( FEAD.CF_ITEM=1 OR FEAD.CF_ITEM=54 OR FEAD.CF_ITEM=55) THEN FEAD.DUE_AMOUNT ELSE 0 END ) CON_PRI_INT_AMOUNT, SUM( CASE WHEN FEAD.BUSINESS_TYPE='LON_WITHDRAW' THEN FEAD.DUE_AMOUNT ELSE 0 END ) LON_WITHDRAW_AMOUNT, SUM( CASE WHEN FEAD.BUSINESS_TYPE='CON_RECEIPT' AND FEAD.CF_ITEM!=1 AND FEAD.CF_ITEM!=54 AND FEAD.CF_ITEM!=55 THEN FEAD.DUE_AMOUNT ELSE 0 END ) CON_OTHER_AMOUNT, SUM( CASE WHEN FEAD.BUSINESS_TYPE='FUND_TRANSFER' THEN FEAD.DUE_AMOUNT ELSE 0 END ) FUND_TRANSFER_AMOUNT, SUM( CASE WHEN FEAD.BUSINESS_TYPE='CON_REPAYMENT' THEN FEAD.DUE_AMOUNT ELSE 0 END ) CON_REPAYMENT_AMOUNT , SUM( CASE WHEN FEAD.BUSINESS_TYPE='LON_REPAYMENT' THEN FEAD.DUE_AMOUNT ELSE 0 END ) LON_REPAYMENT_AMOUNT, SUM( CASE WHEN FEAD.BUSINESS_TYPE='LON_FEE' THEN FEAD.DUE_AMOUNT ELSE 0 END ) LON_FEE_AMOUNT FROM (
) FEAD WHERE FEAD.DUE_DATE>=#{startPeriod} AND FEAD.DUE_DATE<=#{endPeriod} GROUP BY FEAD.BANK_ACCOUNT_ID ) CLA ON CLA.BANK_ACCOUNT_ID=CBA.BANK_ACCOUNT_ID WHERE 1=1
AND CBA.CURRENCY = #{currency}
AND CBA.BANK_ID = #{bankId}
AND CBA.COMPANY_ID = #{companyId}
AND CBA.BANK_ACCOUNT_ID = #{bankAccountId}

WITH BALANCE AS ( SELECT BANK_ACCOUNT_ID, BALANCE_DATE, ACCOUNT_BALANCE FROM ( SELECT -- ROW_NUMBER() OVER(PARTITION BY AB.BANK_ACCOUNT_ID ORDER BY AB.BALANCE_DATE DESC -- ) RN, IF ( @p = AB.BANK_ACCOUNT_ID, @rank := @rank + 1 ,@rank := 1 ) AS RN, @p := AB.BANK_ACCOUNT_ID as rank1, AB.BANK_ACCOUNT_ID, AB.BALANCE_DATE, AB.ACCOUNT_BALANCE FROM CAP_ACCOUNT_MONTHLY_BALANCE AB,(SELECT @p := NULL ,@q := NULL ,@rank := 0) r WHERE AB.BALANCE_DATE <=#{balanceDate} ) WHERE RN = 1 ) SELECT SUM( nvl(INCOME.INCOME_AMOUNT,0)+nvl(BALANCE.ACCOUNT_BALANCE,0)) ACCOUNT_BALANCE, SUM((case when CBA.VALID_FLAG = 'Y' then 0 else nvl(INCOME.INCOME_AMOUNT,0)+nvl(BALANCE.ACCOUNT_BALANCE,0) end)) AVAILABLE_AMOUNT, SUM((case when CBA.VALID_FLAG ='Y' then nvl(INCOME.INCOME_AMOUNT,0)+nvl(BALANCE.ACCOUNT_BALANCE,0) else 0 end)) RESTRICTED_AMOUNT, SUM(nvl(INV.UNLIMITED_AMOUNT,0)) INV_UNLIMITED_AMOUNT, SUM(nvl(INV.LIMITED_AMOUNT,0)) INV_LIMITED_AMOUNT FROM CSH_BANK_ACCOUNT CBA JOIN CSH_BANK CB ON CB.BANK_ID=CBA.BANK_ID LEFT JOIN ( SELECT CASH.BANK_ACCOUNT_ID, nvl(SUM(CASH.TRANSACTION_AMOUNT),0) INCOME_AMOUNT FROM ( --收款 SELECT CT.BANK_ACCOUNT_ID, CT.TRANSACTION_AMOUNT, CT.TRANSACTION_DATE FROM CSH_TRANSACTION CT WHERE CT.REVERSED_FLAG = 'N' AND CT.TRANSACTION_TYPE = 'RECEIPT' --退款 UNION ALL SELECT CT.BANK_ACCOUNT_ID, -CT.TRANSACTION_AMOUNT, CT.TRANSACTION_DATE FROM CSH_TRANSACTION CT WHERE CT.REVERSED_FLAG = 'N' AND CT.TRANSACTION_TYPE = 'REFUND' UNION ALL --付款 SELECT CT.BANK_ACCOUNT_ID, -CT.TRANSACTION_AMOUNT, CT.TRANSACTION_DATE FROM CSH_TRANSACTION CT WHERE CT.REVERSED_FLAG = 'N' AND CT.TRANSACTION_TYPE = 'PAYMENT' UNION ALL --融资收款 SELECT CLCBA.BANK_ACCOUNT_ID, LCW.DUE_AMOUNT, LCW.DUE_DATE FROM LON_CONTRACT_WITHDRAW LCW JOIN CT_LON_CONTRACT_BANK_ACCOUNT CLCBA ON CLCBA.BANK_ACCOUNT_TYPE = 'WITHDRAWAL_ACCOUNT' AND CLCBA.CONTRACT_ID = LCW.CONTRACT_ID WHERE LCW.DATA_CLASS = 'NORMAL' AND LCW.WITHDRAW_STATUS IN ('APPROVED', 'PENDING') UNION ALL --融资还款 SELECT LCRN.BANK_ACCOUNT_ID, -LCRN.DUE_AMOUNT, LCRN.DUE_DATE FROM LON_CONTRACT_WITHDRAW LCW JOIN LON_CONTRACT_REPAYMENT_LN LCRN ON LCW.WITHDRAW_ID = LCRN.WITHDRAW_ID WHERE LCW.DATA_CLASS = 'NORMAL' UNION ALL --资金调拨 拨出 SELECT EFTL.OUT_BANK_ACCOUNT_ID, -EFTL.ACTUAL_PAY_AMOUNT, EFTL.ACTUAL_PAY_DATE FROM EFT_FUND_TRANSFER_LIST EFTL WHERE EFTL.TRANSFER_STATUS = 'CONFIRM' AND EFTL.DATA_CLASS = 'NORMAL' AND EFTL.TRANSFER_TYPE IN ('TRANSFER', 'PAY') AND ( nvl(EFTL.SOURCE_DOC_CATEGORY, 'N') != 'LON_CONTRACT_REPAYMENT' OR ( EFTL.SOURCE_DOC_CATEGORY = 'LON_CONTRACT_REPAYMENT' AND nvl(EFTL.TRANSFER_TYPE, 'N') != 'PAY')) UNION ALL --资金调拨 拨入 SELECT EFTL.IN_BANK_ACCOUNT_ID, EFTL.ACTUAL_PAY_AMOUNT, EFTL.ACTUAL_PAY_DATE FROM EFT_FUND_TRANSFER_LIST EFTL WHERE EFTL.TRANSFER_STATUS = 'CONFIRM' AND EFTL.DATA_CLASS = 'NORMAL' AND EFTL.TRANSFER_TYPE IN ('TRANSFER', 'PAY') AND ( nvl(EFTL.SOURCE_DOC_CATEGORY, 'N') != 'LON_CONTRACT_REPAYMENT' OR ( EFTL.SOURCE_DOC_CATEGORY = 'LON_CONTRACT_REPAYMENT' AND nvl(EFTL.TRANSFER_TYPE, 'N') != 'PAY')) UNION ALL --ABS/ABN 资产转让收款确认 SELECT CBBA.BANK_ACCOUNT_ID, CAPR.RECEIPT_AMOUNT, CAPR.RECEIPT_DATE FROM CT_ABS_PRODUCT CAP JOIN CT_ABS_PRODUCT_RECEIPT CAPR ON CAP.PRODUCT_ID = CAPR.PRODUCT_ID JOIN CT_ABS_BANK_ACCOUNT CBBA ON CBBA.ABS_BANK_ACCOUNT_ID = CAPR.ABS_BANK_ACCOUNT_ID WHERE CAP.DATA_CLASS = 'NORMAL' AND CAP.PRODUCT_STATUS IN ('APPROVED', 'PENDING') UNION ALL --ABS/ABN 回购 SELECT CAPB.BANK_ACCOUNT_ID, -CAPB.BUYBACK_AMOUNT, CAPB.BUYBACK_DATE FROM CT_ABS_PRODUCT_BUYBACK CAPB JOIN CT_ABS_PRODUCT CAP ON CAPB.PRODUCT_ID = CAP.PRODUCT_ID WHERE CAP.DATA_CLASS = 'NORMAL' AND CAP.BUYBACK_STATUS = 'APPROVED' UNION ALL --其他发债收款 SELECT CABA.BANK_ACCOUNT_ID, CAP.ISSUE_AMOUNT, CAP.DUE_DATE_BEGIN FROM CT_ABS_PRODUCT CAP JOIN CT_ABS_BANK_ACCOUNT CABA ON CAP.PRODUCT_ID = CABA.SOURCE_KEY AND CABA.SOURCE_TYPE = 'ABS_PRODUCT' AND CABA.BANK_ACCOUNT_TYPE = 'REG_REC_ACCOUNT' AND CABA.ACCOUNT_SOURCE_TYPE = 'OUR_ACCOUNT' WHERE CAP.DATA_CLASS = 'NORMAL' AND CAP.PRODUCT_STATUS IN ('APPROVED', 'PENDING')) CASH LEFT JOIN BALANCE ON CASH.BANK_ACCOUNT_ID=BALANCE.BANK_ACCOUNT_ID WHERE ( BALANCE.BALANCE_DATE IS NULL OR CASH.TRANSACTION_DATE> BALANCE.BALANCE_DATE ) AND CASH.TRANSACTION_DATE<=#{balanceDate} GROUP BY CASH.BANK_ACCOUNT_ID) INCOME ON CBA.BANK_ACCOUNT_ID=INCOME.BANK_ACCOUNT_ID LEFT JOIN BALANCE ON CBA.BANK_ACCOUNT_ID=BALANCE.BANK_ACCOUNT_ID LEFT JOIN ( SELECT IFP.BANK_ACCOUNT_ID, SUM((case when IFP.IS_LIMITED ='Y' then (IFP.PURCHASED_AMOUNT-IFP.REDEEMED_AMOUNT)else 0 end)) UNLIMITED_AMOUNT, SUM((case when nvl(IFP.IS_LIMITED,'N') ='N' then (IFP.PURCHASED_AMOUNT-IFP.REDEEMED_AMOUNT) else 0 end)) LIMITED_AMOUNT FROM INV_FINANCE_PURCHASE IFP GROUP BY IFP.BANK_ACCOUNT_ID) INV ON CBA.BANK_ACCOUNT_ID= INV.BANK_ACCOUNT_ID WHERE 1=1
AND CBA.CURRENCY=#{currency}
AND CBA.COMPANY_ID=#{companyId}
AND CB.BANK_NAME LIKE CONCAT(concat('%',#{bankName}),'%')
